CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS samples (
    file_hash TEXT PRIMARY KEY,
    source_path TEXT,
    file_name TEXT,
    source_ext TEXT,
    width INTEGER,
    height INTEGER,
    duration_secs DOUBLE PRECISION,
    frame_count INTEGER,
    file_size_bytes BIGINT,
    fps DOUBLE PRECISION,
    has_embedded_icc BOOLEAN,
    has_complex_color_profile BOOLEAN,
    has_transparency BOOLEAN,
    palette_size INTEGER,
    frame_payload_variation DOUBLE PRECISION,
    frame_delay_variation DOUBLE PRECISION,
    temporal_bpp DOUBLE PRECISION,
    spatial_bpp DOUBLE PRECISION,
    aspect_ratio DOUBLE PRECISION,
    total_pixels BIGINT,
    loop_frequency DOUBLE PRECISION,
    is_meme_platform BOOLEAN,
    is_human_semantic_name BOOLEAN,
    cadence_score DOUBLE PRECISION,
    directory_meme_hint BOOLEAN,
    is_high_value_source BOOLEAN,
    is_native_gif BOOLEAN,
    palette_depth DOUBLE PRECISION,
    motion_gini DOUBLE PRECISION,
    block_skew DOUBLE PRECISION,
    temporal_flatness DOUBLE PRECISION,
    loss_tolerance TEXT,
    labeled_by TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    features vector(18)
);

CREATE TABLE IF NOT EXISTS sample_metadata (key TEXT PRIMARY KEY, value TEXT);
